Script.script:
aardwolf_help = aardwolf_help or {}
aardwolf_help.state = aardwolf_help.state or {}

function aardwolf_help.state.record(key, value)
  aardwolf_help.state.values = aardwolf_help.state.values or {}
  aardwolf_help.state.values[key] = value
  aardwolf_help.state.update_count = (aardwolf_help.state.update_count or 0) + 1
end

function aardwolf_help.state.reset()
  aardwolf_help.state.values = {}
  aardwolf_help.state.update_count = 0
end

function aardwolf_help.state.summary()
  return "updates=" .. tostring(aardwolf_help.state.update_count or 0)
end

aardwolf_help = aardwolf_help or {}
aardwolf_help.settings = aardwolf_help.settings or {}

function aardwolf_help.settings.is_enabled()
  return aardwolf_help.settings.enabled ~= false
end

function aardwolf_help.settings.set_enabled(enabled)
  aardwolf_help.settings.enabled = enabled and true or false
end

aardwolf_help = aardwolf_help or {}
aardwolf_help.ui = aardwolf_help.ui or {}

function aardwolf_help.ui.message(message)
  echo("\n[aardwolf-help] " .. tostring(message) .. "\n")
end

function aardwolf_help.ui.status(summary)
  aardwolf_help.ui.message("Status: " .. tostring(summary))
end

aardwolf_help = aardwolf_help or {}
aardwolf_help.commands = aardwolf_help.commands or {}

function aardwolf_help.commands.status()
  aardwolf_help.ui.status(aardwolf_help.state.summary())
end

function aardwolf_help.commands.set_enabled(enabled)
  aardwolf_help.settings.set_enabled(enabled)
  aardwolf_help.ui.message(enabled and "Enabled." or "Disabled.")
end

function aardwolf_help.commands.toggle()
  aardwolf_help.commands.set_enabled(not aardwolf_help.settings.is_enabled())
end

function aardwolf_help.commands.reset()
  aardwolf_help.state.reset()
  aardwolf_help.ui.message("State reset.")
end

aardwolf_help = aardwolf_help or {}
aardwolf_help.protocol = aardwolf_help.protocol or {}

function aardwolf_help.protocol.describe()
  return "Accessible in-client help and migration guidance."
end

aardwolf_help = aardwolf_help or {}
aardwolf_help.lifecycle = aardwolf_help.lifecycle or {}

function aardwolf_help.lifecycle.initialize()
end

function aardwolf_help.lifecycle.shutdown()
end

aardwolf_help.lifecycle.initialize()

aardwolf_help = aardwolf_help or {}
aardwolf_help.help = aardwolf_help.help or {}

function aardwolf_help.help.summary()
  return "Accessible in-client help and migration guidance."
end
